import { inspect } from "node:util";
import { formatTimestamp } from "./utils.js";
export class Formatter {
}
export class PrettyPrintFormatter extends Formatter {
    formatTranscript(transcript, options = {}) {
        return inspect(transcript.toRawData(), {
            colors: false,
            compact: false,
            depth: null,
            maxArrayLength: null,
            ...options,
        });
    }
    formatTranscripts(transcripts, options = {}) {
        return inspect(transcripts.map((transcript) => transcript.toRawData()), { colors: false, compact: false, depth: null, maxArrayLength: null, ...options });
    }
}
export class JSONFormatter extends Formatter {
    formatTranscript(transcript, options = {}) {
        return JSON.stringify(transcript.toRawData(), options.replacer, options.space);
    }
    formatTranscripts(transcripts, options = {}) {
        return JSON.stringify(transcripts.map((transcript) => transcript.toRawData()), options.replacer, options.space);
    }
}
export class TextFormatter extends Formatter {
    formatTranscript(transcript) {
        return transcript.snippets.map((line) => line.text).join("\n");
    }
    formatTranscripts(transcripts) {
        return transcripts.map((transcript) => this.formatTranscript(transcript)).join("\n\n\n");
    }
}
class TextBasedFormatter extends TextFormatter {
    formatTranscript(transcript) {
        const lines = transcript.snippets.map((snippet, index) => {
            const end = snippet.start + snippet.duration;
            const nextStart = transcript.snippets[index + 1]?.start;
            const effectiveEnd = nextStart !== undefined && nextStart < end ? nextStart : end;
            const timeText = `${formatTimestamp(snippet.start, this.timestampSeparator)} --> ${formatTimestamp(effectiveEnd, this.timestampSeparator)}`;
            return this.formatTranscriptLine(index, timeText, snippet);
        });
        return this.formatTranscriptHeader(lines);
    }
}
export class SRTFormatter extends TextBasedFormatter {
    timestampSeparator = ",";
    formatTranscriptHeader(lines) {
        return `${lines.join("\n\n")}\n`;
    }
    formatTranscriptLine(index, timeText, snippet) {
        return `${index + 1}\n${timeText}\n${snippet.text}`;
    }
}
export class WebVTTFormatter extends TextBasedFormatter {
    timestampSeparator = ".";
    formatTranscriptHeader(lines) {
        return `WEBVTT\n\n${lines.join("\n\n")}\n`;
    }
    formatTranscriptLine(_index, timeText, snippet) {
        return `${timeText}\n${snippet.text}`;
    }
}
export class UnknownFormatterType extends Error {
    constructor(formatterType) {
        super(`The format '${formatterType}' is not supported. Choose one of the following formats: ${Object.keys(FormatterLoader.TYPES).join(", ")}`);
        this.name = "UnknownFormatterType";
    }
}
export class FormatterLoader {
    static TYPES = {
        json: JSONFormatter,
        pretty: PrettyPrintFormatter,
        srt: SRTFormatter,
        text: TextFormatter,
        webvtt: WebVTTFormatter,
    };
    load(formatterType = "pretty") {
        const FormatterType = FormatterLoader.TYPES[formatterType];
        if (!FormatterType) {
            throw new UnknownFormatterType(formatterType);
        }
        return new FormatterType();
    }
}
